insert into public.pageant_activities(id,project_id,kind,title,description,status,starts_at,venue,amount,terms,refund_policy,config) values('2218dddc-9f96-53b9-bc08-5fcfcfa7b3f3','d2acc4c7-3412-4df2-8c2d-0df2020245d5','pageant','2027 台灣小姐｜參賽意願登記','先登記妳的參賽意願，於正式簡章公布後再依條件提出申請。這不是正式參賽報名，不保證入選，不收參賽費；五場比賽日期及資格另行公告。','open','2026-11-15T00:00:00+08:00','線上意願登記，非實體比賽日期',0,'本頁僅為2027台灣小姐選拔的免費意願登記，資料僅供本屆主辦處理招募與聯繫使用，不作其他品牌行銷。登記不等於正式報名、錄取、席次確認或取得國際賽事資格。2027年年齡、身高、國籍等參賽資格、費用、日期、肖像及素材授權以正式簡章為準，不沿用舊屆。請勿在補充說明填寫證件號碼、病歷等敏感資訊。如欲撤回或修正，請透過本網站所連結之台灣小姐官方粉專聯繫主辦。','本意願登記不收取費用，沒有付款或退款交易；正式比賽、課程或門票的收費與退費條款另行公告。','{"registration_mode":"interest","not_admission":true,"seed":"miss-taiwan-2027-v1"}'::jsonb) on conflict do nothing;
insert into public.pageant_activities(id,project_id,kind,title,description,status,starts_at,venue,amount,terms,refund_policy,config) values('37b21910-cfa9-5bde-9db1-c6e2d18dedf5','d2acc4c7-3412-4df2-8c2d-0df2020245d5','press','2027 台灣小姐｜媒體採訪意願登記','2026年12月中預定舉行年度計畫啟動記者會。媒體可先留下採訪意願，補充說明請填媒體名稱、採訪方向與所需協助。日期、場地、席次及拍攝安排由主辦另行確認。','open','2026-11-15T00:00:00+08:00','線上意願登記，非實體比賽日期',0,'本頁僅為2027台灣小姐選拔的免費意願登記，資料僅供本屆主辦處理招募與聯繫使用，不作其他品牌行銷。登記不等於正式報名、錄取、席次確認或取得國際賽事資格。2027年年齡、身高、國籍等參賽資格、費用、日期、肖像及素材授權以正式簡章為準，不沿用舊屆。請勿在補充說明填寫證件號碼、病歷等敏感資訊。如欲撤回或修正，請透過本網站所連結之台灣小姐官方粉專聯繫主辦。','本意願登記不收取費用，沒有付款或退款交易；正式比賽、課程或門票的收費與退費條款另行公告。','{"registration_mode":"interest","not_admission":true,"seed":"miss-taiwan-2027-v1"}'::jsonb) on conflict do nothing;
