insert into public.pageant_sponsor_packages(id,project_id,title,summary,kind,amount,benefits,status) values('72988c48-5f29-5fef-ad22-f13e18bd66d3','d2acc4c7-3412-4df2-8c2d-0df2020245d5','品牌與物資合作','邀請美妝、保養、生活風格與活動用品品牌，共同討論適合的支持方式。以下為洽談方向，數量、露出及使用方式依雙方確認。','inkind',null,'["產品或物資需求與交付窗口洽談","品牌內容與肖像素材授權另行確認","依實際履約整理個別品牌結案紀錄"]'::jsonb,'published') on conflict do nothing;
