insert into public.pageant_sponsor_packages(id,project_id,title,summary,kind,amount,benefits,status) values('bdf2ee86-0e46-537c-988d-742c365828c0','d2acc4c7-3412-4df2-8c2d-0df2020245d5','媒體與影像合作','邀請媒體、攝影、影音與內容團隊，從年度啟動到賽後結案共同規劃故事。未承諾特定播出或曝光數字。','media',null,'["記者會採訪及內容方向洽談","新聞、人物與幕後紀錄素材協作","發布連結與授權範圍核對"]'::jsonb,'published') on conflict do nothing;
