insert into public.pageant_campaigns(id,project_id,activity_id,title,channel,caption,status) values('17b765d4-bf7e-5ba7-8bd4-e03809bd9993','d2acc4c7-3412-4df2-8c2d-0df2020245d5',null,'培訓計畫形象內容','instagram','從儀態、鏡頭表達，到文化敘事，陪妳準備每一個舞台。講師與課表尚待確認。配圖為AI形象示意，非實際課程紀錄。','draft') on conflict do nothing;
insert into public.pageant_campaigns(id,project_id,activity_id,title,channel,caption,status) values('dd91b185-9562-5a11-aba3-8d87459ca107','d2acc4c7-3412-4df2-8c2d-0df2020245d5',null,'品牌合作邀請','line','邀請品牌、服裝、場地、媒體與影像團隊，共同提案2027台灣小姐。權益、交付與費用依雙方確認，非已簽約公告。','draft') on conflict do nothing;
