insert into public.pageant_run_items(id,project_id,activity_id,title,position,cue,preparation,public,status) values('057cf6f9-b3f2-54db-86d1-06209986583c','d2acc4c7-3412-4df2-8c2d-0df2020245d5','f5d47ab1-d5f6-508b-812a-19213313539e','合影、素材交付與會後聯繫',4,'待確認實際時長、出席人員、座位及媒體拍攝範圍；請勿代擬受訪者原話。','預定2026年12月中，確切時程與窗口待確認。',false,'draft') on conflict do nothing;
insert into public.pageant_work_items(id,project_id,kind,stage,title,payload) values('eb2ec7ec-b78d-5ef0-88cb-581bdb01a291','d2acc4c7-3412-4df2-8c2d-0df2020245d5','schedule','planning','2026年12月中｜啟動記者會籌備','{"activity_id":"f5d47ab1-d5f6-508b-812a-19213313539e","note":"12月中為主辦提供之預定期間，不能擅填單一天。","checklist":["確認日期與場地","確認主持、主辦及發言窗口","媒體、嘉賓及品牌邀請","新聞稿與媒體資料包","確認五場賽制與招募簡章發布範圍","攝影、背板與動線","採訪、肖像與素材授權"],"dependencies":[]}'::jsonb) on conflict do nothing;
insert into public.pageant_proposals(id,project_id,title,kind,status,content) values('034084d6-202e-577a-b66a-a956680553ba','d2acc4c7-3412-4df2-8c2d-0df2020245d5','2027台灣小姐｜五場選拔年度執行模板','proposal','draft','{"body":"2027台灣小姐年度選拔計畫\n\n預定2026年12月中舉行年度啟動記者會。確切日期、時間、場地與出席方式另行確認。\n\n1. 海選\n自我介紹、參賽動機與個人故事，從真誠的表達開始。\n準備：確認正式簡章與報名截止日；審查參賽資格與個資同意；分組面談與評審迴避；通知錄取及候補名單\n\n2. 初賽（才藝）\n用音樂、舞蹈、藝術或創作，說出屬於自己的故事。\n準備：收齊音樂檔與演出授權；確認器材、用電與安全需求；安排逐位彩排與計時；確認評分、同分與晉級規則\n\n3. 泳裝 & 禮服賽\n以自信、儀態及服裝呈現，在兩種舞台語言中展現自己。\n準備：確認泳裝及禮服規範與更衣隱私；核對音樂、走位與鞋服安全；落實攝影、肖像及媒體拍攝範圍；完成兩段展示評分與名單核對\n\n4. 國服賽\n從土地、工藝與文化找到靈感，以服裝與敘事傳遞台灣之美。\n準備：收齊設計理念與創作授權；確認文化引用與服裝重量安全；安排展示動線、換裝及翻譯；核對文化敘事與評分紀錄\n\n5. 總決賽\n集結舞台表現、機智問答與個人主張，迎接年度最重要的時刻。\n準備：完成全體彩排、座位與無障礙安排；鎖定評審名單與計分覆核；確認票券、核銷、醫護與緊急應變；主辦核准正式成績與公開名單；完成頒獎、採訪與品牌交付\n\n三項培訓：儀態與鏡頭表達、才藝與舞台實作、文化敘事與國際禮儀。講師、日期、教材、名額與費用待確認。\n\n招募：先免費意願登記，再依正式簡章辦理資格審核、正式報名、錄取與後續培訓。意願核准不等於正式錄取。\n\n合作：品牌方案、嘉賓、媒體、課程、票券、評審及各場流程都連入同一專案；未確認的費用、合作與曝光不列為已完成。\n\n結案：依實際發布連結、品牌交付及交易紀錄，整理新聞、照片與電子會刊。","source":"主辦提供賽制＋流程規劃草稿，需人工確認","blueprint_version":1}'::jsonb) on conflict do nothing;
insert into public.pageant_articles(id,project_id,slug,title,status,content,publication,publish_at) values('27639c52-016c-5eda-a4cb-d0deb75f7d35','d2acc4c7-3412-4df2-8c2d-0df2020245d5','miss-taiwan-2027-season-launch','2027 台灣小姐選拔計畫啟動：預定 12 月中記者會，五場舞台迎接全新旅程','published','{"title":"2027 台灣小姐選拔計畫啟動：預定 12 月中記者會，五場舞台迎接全新旅程","subtitle":"免費參賽意願登記先行開放；正式資格、賽程及費用將另行公告","byline":"台灣小姐｜賽事籌備公告","category":"賽事公告","format_label":"年度計畫預告","photos":[{"url":"https://pageant.self.com.tw/miss-taiwan-2027/campaign.webp","caption":"2027台灣小姐招募AI形象示意，人物為虛構模特兒，非本屆參賽者或賽事實拍。","source":"台灣小姐2027形象製作","kind":"AI形象示意"},{"url":"https://pageant.self.com.tw/miss-taiwan-2027/training.webp","caption":"AI培訓形象示意，非實際講師、學員或課程紀錄。","source":"台灣小姐2027形象製作","kind":"AI形象示意"}],"sources":[{"title":"台灣小姐官方粉專","url":"https://www.facebook.com/Taiwanpageant/"},{"title":"2027台灣小姐年度計畫官網","url":"https://pageant.self.com.tw/miss-taiwan"}],"sections":[{"heading":"從年度啟動，準備下一個舞台","paragraphs":["2027台灣小姐選拔計畫正式展開籌備，預定於2026年12月中舉行年度計畫啟動記者會，公布明年度選拔方向與後續招募安排。確切日期、時間、場地與出席方式，將於主辦確認後透過官網及官方粉專公告。","這一季的舞台，將從自我介紹、才藝與風格表達延伸到文化敘事，邀請懷抱舞台夢想的女性先認識賽事計畫，為下一步準備。"]},{"heading":"五場選拔，記錄不同面向的自信","paragraphs":["年度規劃依序為海選、初賽（才藝）、泳裝與禮服賽、國服賽及總決賽。五場賽事均規劃於2027年，實際日期、城市、場地、參賽名額、評分及晉級辦法待正式公告。","從才藝的準備到國服的文化故事，每一場都將連結招募、培訓與舞台執行。培訓方向包含儀態與鏡頭表達、才藝與舞台實作、文化敘事與國際禮儀；講師、課表與費用另行確認。"]},{"heading":"先登記意願，留意正式簡章","paragraphs":["官網現開放免費參賽意願登記，會員可留下聯絡與參與意願；媒體也可登記記者會採訪意願。這一步不等於正式報名、錄取、記者會席次確認或取得國際賽事資格。","2027年參賽資格、年齡、身高、國籍、正式報名截止日、參賽費與退費規則尚待確認，不直接沿用舊屆資料。目前不收取參賽費，五場比賽也尚未開放售票。"]},{"heading":"邀請品牌與創作團隊，一起參與","paragraphs":["品牌、服裝設計、國服創作、場地、媒體與影像團隊，可透過品牌合作入口提出需求。合作內容、權益、交付與費用須由雙方確認；尚未確認的支持不列作已簽約贊助。","官網的招募與培訓形象圖為AI製作，與未來的真實參賽者、課程及現場紀錄分開呈現。後續採訪與實拍將在取得同意及確認內容後陸續公開。"]}]}'::jsonb,'{"title":"2027 台灣小姐選拔計畫啟動：預定 12 月中記者會，五場舞台迎接全新旅程","subtitle":"免費參賽意願登記先行開放；正式資格、賽程及費用將另行公告","byline":"台灣小姐｜賽事籌備公告","category":"賽事公告","format_label":"年度計畫預告","photos":[{"url":"https://pageant.self.com.tw/miss-taiwan-2027/campaign.webp","caption":"2027台灣小姐招募AI形象示意，人物為虛構模特兒，非本屆參賽者或賽事實拍。","source":"台灣小姐2027形象製作","kind":"AI形象示意"},{"url":"https://pageant.self.com.tw/miss-taiwan-2027/training.webp","caption":"AI培訓形象示意，非實際講師、學員或課程紀錄。","source":"台灣小姐2027形象製作","kind":"AI形象示意"}],"sources":[{"title":"台灣小姐官方粉專","url":"https://www.facebook.com/Taiwanpageant/"},{"title":"2027台灣小姐年度計畫官網","url":"https://pageant.self.com.tw/miss-taiwan"}],"sections":[{"heading":"從年度啟動，準備下一個舞台","paragraphs":["2027台灣小姐選拔計畫正式展開籌備，預定於2026年12月中舉行年度計畫啟動記者會，公布明年度選拔方向與後續招募安排。確切日期、時間、場地與出席方式，將於主辦確認後透過官網及官方粉專公告。","這一季的舞台，將從自我介紹、才藝與風格表達延伸到文化敘事，邀請懷抱舞台夢想的女性先認識賽事計畫，為下一步準備。"]},{"heading":"五場選拔，記錄不同面向的自信","paragraphs":["年度規劃依序為海選、初賽（才藝）、泳裝與禮服賽、國服賽及總決賽。五場賽事均規劃於2027年，實際日期、城市、場地、參賽名額、評分及晉級辦法待正式公告。","從才藝的準備到國服的文化故事，每一場都將連結招募、培訓與舞台執行。培訓方向包含儀態與鏡頭表達、才藝與舞台實作、文化敘事與國際禮儀；講師、課表與費用另行確認。"]},{"heading":"先登記意願，留意正式簡章","paragraphs":["官網現開放免費參賽意願登記，會員可留下聯絡與參與意願；媒體也可登記記者會採訪意願。這一步不等於正式報名、錄取、記者會席次確認或取得國際賽事資格。","2027年參賽資格、年齡、身高、國籍、正式報名截止日、參賽費與退費規則尚待確認，不直接沿用舊屆資料。目前不收取參賽費，五場比賽也尚未開放售票。"]},{"heading":"邀請品牌與創作團隊，一起參與","paragraphs":["品牌、服裝設計、國服創作、場地、媒體與影像團隊，可透過品牌合作入口提出需求。合作內容、權益、交付與費用須由雙方確認；尚未確認的支持不列作已簽約贊助。","官網的招募與培訓形象圖為AI製作，與未來的真實參賽者、課程及現場紀錄分開呈現。後續採訪與實拍將在取得同意及確認內容後陸續公開。"]}]}'::jsonb,'2026-11-15T00:00:00+08:00') on conflict do nothing;
